import {GPUMaterialBaker} from '../material-production/gpu.js';
import {MAPS,encodeMaterialPack,decodeMaterialPack} from '../material-production/pack.js';
import {optimizedBuilding} from './model.js';
const linear=c=>c<=.04045?c/12.92:((c+.055)/1.055)**2.4;
export class GraphGPU{
 constructor(device){this.device=device;this.building=new GPUMaterialBaker(device);this.pipeline=null;}
 async init(){if(this.pipeline)return 0;const start=performance.now(),d=this.device,shader=async path=>{const module=d.createShaderModule({code:await(await fetch(new URL(path,import.meta.url))).text()});const errors=(await module.getCompilationInfo()).messages.filter(m=>m.type==='error');if(errors.length)throw Error(errors.map(e=>e.message).join('\n'));return module;},a=await shader('./graph.wgsl'),b=await shader('./transpose.wgsl'),c=await shader('../material-production/mip.wgsl');this.pipeline={graph:await d.createComputePipelineAsync({layout:'auto',compute:{module:a,entryPoint:'main'}}),interleave:await d.createComputePipelineAsync({layout:'auto',compute:{module:b,entryPoint:'interleave'}}),split:await d.createComputePipelineAsync({layout:'auto',compute:{module:b,entryPoint:'split'}}),mip:await d.createComputePipelineAsync({layout:'auto',compute:{module:c,entryPoint:'main'}})};return performance.now()-start;}
 async bake(program,n,sourceCPU){const specialized=optimizedBuilding(program);if(specialized){const r=await this.building.bake(specialized.recipe,n,{zone:specialized.zone});r.recipe={...program.graph,weather:specialized.recipe.weather};const read=r.readback;r.readback=()=>read(r.recipe);r.sourceCPUms=0;return r;}
 const initMs=await this.init(),d=this.device,start=performance.now(),resources=[],sourceResults=[],cache=new Map(),buffers=(bytes,usage=GPUBufferUsage.STORAGE|GPUBufferUsage.COPY_SRC|GPUBufferUsage.COPY_DST)=>{const b=d.createBuffer({size:bytes,usage});resources.push(b);return b;},dispatch=(pipeline,entries,count,two=false)=>{const encoder=d.createCommandEncoder(),pass=encoder.beginComputePass();pass.setPipeline(pipeline);pass.setBindGroup(0,d.createBindGroup({layout:pipeline.getBindGroupLayout(0),entries:entries.map(([binding,buffer])=>({binding,resource:{buffer}}))}));if(two)pass.dispatchWorkgroups(Math.ceil(n/8),Math.ceil(n/8));else pass.dispatchWorkgroups(Math.ceil(count/64));pass.end();d.queue.submit([encoder.finish()]);};let sourceCPUms=0,nestedInitMs=0;const dummy=buffers(12);
 const interleave=(base)=>{const out=buffers(n*n*12);dispatch(this.pipeline.interleave,[[0,base.color],[1,base.normal],[2,base.surface],[3,out]],n*n);return out;};
 async function visit(node,engine){if(cache.has(node.id))return cache.get(node.id);const special=optimizedBuilding({root:node});let result;if(special){const baked=await engine.building.bake(special.recipe,n,{zone:special.zone});sourceResults.push(baked);nestedInitMs+=baked.timings.initMs||0;result=interleave(baked.levels[0].buffers);}else if(['bitmap','urban','hull','scan','pack','localPack'].includes(node.kind)){const begin=performance.now(),pack=await sourceCPU(node,n);sourceCPUms+=performance.now()-begin;const base={};for(const id of MAPS){base[id]=buffers(n*n*4);d.queue.writeBuffer(base[id],0,pack.maps[id][0].data);}result=interleave(base);}else if(node.kind==='noise')result=node.params;else{const p=node.params,words=new Uint32Array(32),f=new Float32Array(words.buffer),mode={growth:0,finish:1,weather:2,blend:3}[node.kind];words[0]=mode;words[1]=n;words[2]=Number(p.seed??17)>>>0;words[3]=['moss','lichen','snow','dust'].indexOf(p.kind);const color=p.color||'#52753c',tint=p.tint||'#ffffff';f.set([1,3,5].map(i=>linear(parseInt(color.slice(i,i+2),16)/255)),4);f[7]=p.roughness??.85;f[8]=p.relief??1;f[9]=p.normalStrength??1;f.set([1,3,5].map(i=>linear(parseInt(tint.slice(i,i+2),16)/255)),10);f[13]=p.amount??.6;f[14]=p.heightBlend??.35;words[15]=['noise','uniform','cavity','height'].indexOf(p.mode);if(words[15]>3)words[15]=p.mode==='upward'?3:0;let a=dummy,b=dummy,mask;if(node.kind!=='growth')a=await visit(node.inputs[node.kind==='blend'?'base':'in'],engine);if(node.inputs.layer)b=await visit(node.inputs.layer,engine);if(node.inputs.mask)mask=await visit(node.inputs.mask,engine);words[16]=Number(mask?.seed??p.seed??17)>>>0;f[17]=mask?.scale??8;f[18]=mask?.coverage??.6;f[19]=mask?.softness??.18;words[20]=mask?.invert?1:0;words[21]=mask?1:0;f[22]=p.grime??.35;f[23]=p.wetness??0;const params=buffers(words.byteLength);d.queue.writeBuffer(params,0,words);result=buffers(n*n*12);dispatch(engine.pipeline.graph,[[0,params],[1,a],[2,b],[3,result]],n*n,true);}cache.set(node.id,result);return result;}
 try{const root=await visit(program.root,this),base={width:n,height:n,buffers:Object.fromEntries(MAPS.map(id=>[id,buffers(n*n*4)]))};dispatch(this.pipeline.split,[[4,root],[5,base.buffers.color],[6,base.buffers.normal],[7,base.buffers.surface]],n*n);await d.queue.onSubmittedWorkDone();const synthesisMs=performance.now()-start-nestedInitMs,mipStart=performance.now(),levels=[base];for(let size=n/2;size>=8;size/=2){const previous=levels.at(-1),next={width:size,height:size,buffers:Object.fromEntries(MAPS.map(id=>[id,buffers(size*size*4)]))},config=buffers(16,GPUBufferUsage.UNIFORM|GPUBufferUsage.COPY_DST);d.queue.writeBuffer(config,0,new Uint32Array([size,size,size,0]));const encoder=d.createCommandEncoder(),pass=encoder.beginComputePass(),pipeline=this.pipeline.mip;pass.setPipeline(pipeline);pass.setBindGroup(0,d.createBindGroup({layout:pipeline.getBindGroupLayout(0),entries:[...MAPS.map(id=>previous.buffers[id]),...MAPS.map(id=>next.buffers[id]),config].map((buffer,binding)=>({binding,resource:{buffer}}))}));pass.dispatchWorkgroups(Math.ceil(size/8),Math.ceil(size/8));pass.end();d.queue.submit([encoder.finish()]);levels.push(next);}await d.queue.onSubmittedWorkDone();const result={recipe:program.graph,size:n,atlas:{columns:1,rows:1,guardFraction:.125},levels,sourceCPUms,timings:{initMs:initMs+nestedInitMs,synthesisMs,mipMs:performance.now()-mipStart,totalMs:performance.now()-start},dispose:()=>{sourceResults.forEach(r=>r.dispose());resources.forEach(b=>b.destroy());},readback:async()=>{const begin=performance.now(),total=levels.reduce((v,l)=>v+l.width*l.height*12,0),read=d.createBuffer({size:total,usage:GPUBufferUsage.COPY_DST|GPUBufferUsage.MAP_READ});try{const encoder=d.createCommandEncoder();let offset=0;for(const id of MAPS)for(const l of levels){const bytes=l.width*l.height*4;encoder.copyBufferToBuffer(l.buffers[id],0,read,offset,bytes);offset+=bytes;}d.queue.submit([encoder.finish()]);await read.mapAsync(GPUMapMode.READ);const bytes=new Uint8Array(read.getMappedRange().slice(0));read.unmap();let at=0;const output=levels.map(l=>({width:l.width,height:l.height}));for(const id of MAPS)for(let i=0;i<levels.length;i++){const bytesLength=levels[i].width*levels[i].height*4;output[i][id]=bytes.subarray(at,at+bytesLength);at+=bytesLength;}return{bytes:encodeMaterialPack({recipe:program.graph,levels:output,producer:sourceCPUms?'graph-hybrid':'graph-gpu',atlas:result.atlas}),timings:{readbackMs:performance.now()-begin}};}finally{read.destroy();}}};return result;
 }catch(e){sourceResults.forEach(r=>r.dispose());resources.forEach(b=>b.destroy());throw e;}
 }
}
